dashboard.definition:
{
  "title": "OBTS: Hunting macOS with synthetic eslogger",
  "description": "Stage dashboard for the EvidenceForge macOS demo. Each tab is one hunt; panels run the app's saved searches over all time.",
  "theme": "light",
  "dataSources": {
    "ds_ov_mix": {
      "type": "ds.search",
      "name": "OBTS 00 - ES event mix per Mac",
      "options": {
        "query": "| savedsearch \"OBTS 00 - ES event mix per Mac\" | table host_short exec fork exit open close write create btm_launch_item_add openssh_login lw_session_lock",
        "queryParameters": {
          "earliest": "0",
          "latest": "now"
        }
      }
    },
    "ds_ov_stack": {
      "type": "ds.search",
      "name": "OBTS 01 - Stack non-Apple code that executed",
      "options": {
        "query": "| savedsearch \"OBTS 01 - Stack non-Apple code that executed\"",
        "queryParameters": {
          "earliest": "0",
          "latest": "now"
        }
      }
    },
    "ds_amos_chain": {
      "type": "ds.search",
      "name": "OBTS AMOS 5 - Full AMOS chain on one host",
      "options": {
        "query": "| savedsearch \"OBTS AMOS 5 - Full AMOS chain on one host\" | eval time=strftime(_time, \"%H:%M:%S.%3N\") | sort 0 _time | eval subject=process_path, detail=case(es_event==\"exec\", cmdline, es_event==\"open\" OR es_event==\"close\", file_path, true(), \"\") | table time es_event pid ppid subject detail",
        "queryParameters": {
          "earliest": "0",
          "latest": "now"
        }
      }
    },
    "ds_amos_1": {
      "type": "ds.search",
      "name": "OBTS AMOS 1 - Ad-hoc signed app bundle launched by launchd",
      "options": {
        "query": "| savedsearch \"OBTS AMOS 1 - Ad-hoc signed app bundle launched by launchd\" | eval time=strftime(_time, \"%H:%M:%S.%3N\") | table time host_short target_path target_team_id uid",
        "queryParameters": {
          "earliest": "0",
          "latest": "now"
        }
      }
    },
    "ds_amos_1b": {
      "type": "ds.search",
      "name": "OBTS AMOS 1b - Ad-hoc launchd jobs by install location and prevalence",
      "options": {
        "query": "| savedsearch \"OBTS AMOS 1b - Ad-hoc launchd jobs by install location and prevalence\" | table location target_path macs on",
        "queryParameters": {
          "earliest": "0",
          "latest": "now"
        }
      }
    },
    "ds_amos_3": {
      "type": "ds.search",
      "name": "OBTS AMOS 3 - Keychain opened by non-Apple code",
      "options": {
        "query": "| savedsearch \"OBTS AMOS 3 - Keychain opened by non-Apple code\" | eval time=strftime(_time, \"%H:%M:%S.%3N\") | table time host_short process_path process_signer process_team_id",
        "queryParameters": {
          "earliest": "0",
          "latest": "now"
        }
      }
    },
    "ds_amos_3b": {
      "type": "ds.search",
      "name": "OBTS AMOS 3b - Keychain opened by code with no Team ID",
      "options": {
        "query": "| savedsearch \"OBTS AMOS 3b - Keychain opened by code with no Team ID\" | table lead process_path process_signer process_team_id on",
        "queryParameters": {
          "earliest": "0",
          "latest": "now"
        }
      }
    },
    "ds_amos_4": {
      "type": "ds.search",
      "name": "OBTS AMOS 4 - Keychain reader egress in Zeek",
      "options": {
        "query": "| savedsearch \"OBTS AMOS 4 - Keychain reader egress in Zeek\" | eval first_seen=substr(first_seen, 12) | table first_seen seconds_after_keychain src_ip id.resp_h id.resp_p sni bytes_out bytes_in keychain_reader",
        "queryParameters": {
          "earliest": "0",
          "latest": "now"
        }
      }
    },
    "ds_bt_chain": {
      "type": "ds.search",
      "name": "OBTS BeaverTail 2 - node -> sh -c -> node chain",
      "options": {
        "query": "| savedsearch \"OBTS BeaverTail 2 - node -> sh -c -> node chain\" | eval time=strftime(_time, \"%H:%M:%S.%3N\") | sort 0 _time | table time host_short sh_cmd child_cmd cwd",
        "queryParameters": {
          "earliest": "0",
          "latest": "now"
        }
      }
    },
    "ds_bt_1": {
      "type": "ds.search",
      "name": "OBTS BeaverTail 1 - Package-manager lifecycle shells",
      "options": {
        "query": "| savedsearch \"OBTS BeaverTail 1 - Package-manager lifecycle shells\" | eval time=strftime(_time, \"%H:%M:%S.%3N\") | table time host_short cmdline cwd",
        "queryParameters": {
          "earliest": "0",
          "latest": "now"
        }
      }
    },
    "ds_bt_3": {
      "type": "ds.search",
      "name": "OBTS BeaverTail 3 - postinstall beacon in Zeek",
      "options": {
        "query": "| savedsearch \"OBTS BeaverTail 3 - postinstall beacon in Zeek\" | eval time=strftime(_time, \"%H:%M:%S.%3N\") | table time seconds_after src_ip sourcetype query server_name id.resp_h id.resp_p",
        "queryParameters": {
          "earliest": "0",
          "latest": "now"
        }
      }
    },
    "ds_bt_3b": {
      "type": "ds.search",
      "name": "OBTS BeaverTail 3b - Where every lifecycle-script node went",
      "options": {
        "query": "| savedsearch \"OBTS BeaverTail 3b - Where every lifecycle-script node went\" | eval script_time=substr(script_time, 12), first_lookup=substr(first_lookup, 12) | table mac script_time query first_lookup",
        "queryParameters": {
          "earliest": "0",
          "latest": "now"
        }
      }
    },
    "ds_cm_join": {
      "type": "ds.search",
      "name": "OBTS CloudMensis 3 - Plist create joined to BTM instigator",
      "options": {
        "query": "| savedsearch \"OBTS CloudMensis 3 - Plist create joined to BTM instigator\" | table host_short masquerade plist writer_path writer_signer",
        "queryParameters": {
          "earliest": "0",
          "latest": "now"
        }
      }
    },
    "ds_cm_1": {
      "type": "ds.search",
      "name": "OBTS CloudMensis 1 - Plist created in a user LaunchAgents dir",
      "options": {
        "query": "| savedsearch \"OBTS CloudMensis 1 - Plist created in a user LaunchAgents dir\" | eval time=strftime(_time, \"%H:%M:%S.%3N\") | table time host_short file_path process_path process_signer",
        "queryParameters": {
          "earliest": "0",
          "latest": "now"
        }
      }
    },
    "ds_cm_2": {
      "type": "ds.search",
      "name": "OBTS CloudMensis 2 - BTM launch item added",
      "options": {
        "query": "| savedsearch \"OBTS CloudMensis 2 - BTM launch item added\" | eval time=strftime(_time, \"%H:%M:%S.%3N\") | table time host_short btm_item_url btm_executable_path btm_instigator_path",
        "queryParameters": {
          "earliest": "0",
          "latest": "now"
        }
      }
    },
    "ds_ssh_1": {
      "type": "ds.search",
      "name": "OBTS SSH 1 - openssh login/logout sessions",
      "options": {
        "query": "| savedsearch \"OBTS SSH 1 - openssh login/logout sessions\" | eval time=strftime(_time, \"%H:%M:%S.%3N\") | eval duration=round(duration, 1) | table time host_short ssh_user ssh_src ssh_success duration eventcount",
        "queryParameters": {
          "earliest": "0",
          "latest": "now"
        }
      }
    },
    "ds_ssh_2": {
      "type": "ds.search",
      "name": "OBTS SSH 2 - SSH sessions in Zeek alongside ES",
      "options": {
        "query": "| savedsearch \"OBTS SSH 2 - SSH sessions in Zeek alongside ES\" | eval time=strftime(_time, \"%H:%M:%S.%3N\") | eval duration=round(duration, 1) | table time id.orig_h src_mac id.resp_h dest_mac duration conn_state orig_bytes resp_bytes",
        "queryParameters": {
          "earliest": "0",
          "latest": "now"
        }
      }
    }
  },
  "visualizations": {
    "viz_ov_intro": {
      "type": "splunk.markdown",
      "options": {
        "markdown": "## Six Macs, two hours of Endpoint Security\nSynthetic `eslogger` NDJSON from **EvidenceForge**, plus Zeek from the core sensor. ES has no network events, so every network pivot goes host \u2192 IP \u2192 Zeek.",
        "fontSize": "large"
      }
    },
    "viz_ov_mix": {
      "type": "splunk.table",
      "title": "ES event mix per Mac",
      "description": "Counts per event type (OBTS 00).",
      "dataSources": {
        "primary": "ds_ov_mix"
      },
      "options": {
        "count": 10,
        "fontSize": "large",
        "showInternalFields": false,
        "columnFormat": {
          "time": {
            "width": 130
          },
          "detail": {
            "width": 760
          },
          "subject": {
            "width": 500
          },
          "target_path": {
            "width": 560
          },
          "process_path": {
            "width": 520
          },
          "cmdline": {
            "width": 560
          },
          "file_path": {
            "width": 460
          },
          "plist": {
